package wordfreq

import (
	"testing"
)

func TestAddAndCount(t *testing.T) {
	wf := New()
	wf.Add("apple")
	wf.Add("banana")
	wf.Add("apple")
	if wf.Count("apple") != 2 {
		t.Errorf("expected 2, got %d", wf.Count("apple"))
	}
	if wf.Count("banana") != 1 {
		t.Errorf("expected 1, got %d", wf.Count("banana"))
	}
	if wf.Count("cherry") != 0 {
		t.Errorf("expected 0, got %d", wf.Count("cherry"))
	}
}

func TestTopN(t *testing.T) {
	wf := New()
	wf.Add("a")
	wf.Add("a")
	wf.Add("a")
	wf.Add("b")
	wf.Add("b")
	wf.Add("c")
	top := wf.TopN(2)
	if len(top) != 2 {
		t.Fatalf("expected 2 results, got %d", len(top))
	}
	if top[0].Word != "a" || top[0].Count != 3 {
		t.Errorf("expected a:3, got %s:%d", top[0].Word, top[0].Count)
	}
	if top[1].Word != "b" || top[1].Count != 2 {
		t.Errorf("expected b:2, got %s:%d", top[1].Word, top[1].Count)
	}
}

func TestTopNMoreThanDistinctWords(t *testing.T) {
	wf := New()
	wf.Add("x")
	top := wf.TopN(5)
	if len(top) != 1 {
		t.Fatalf("expected 1, got %d", len(top))
	}
}

func TestTopNEmpty(t *testing.T) {
	wf := New()
	top := wf.TopN(3)
	if len(top) != 0 {
		t.Fatalf("expected 0, got %d", len(top))
	}
}

func TestCountZeroForUnknown(t *testing.T) {
	wf := New()
	if wf.Count("unknown") != 0 {
		t.Errorf("expected 0 for unseen word")
	}
}

